            if(stage==3){if(ticks<12)return;var m=(AlchemyFurnaceMenu)mc.player.containerMenu;mc.gameMode.handleInventoryButtonClick(m.containerId,249);stage=4;ticks=0;return;}
            if(stage==4){if(ticks<18)return;pending=mc.getSingleplayerServer().submit(()->{check(!furnace(mc).hasResult(),"Ordinary claim not settled");setupPortable(mc);check(HeavenlyFurnace.open(player(mc)),"Heavenly catalogue gate failed");});stage=5;return;}
