            if(stage==7){if(ticks<6)return;var field=HeavenlyFurnaceScreen.class.getDeclaredField("token");field.setAccessible(true);var token=(UUID)field.get(mc.screen);Network.CHANNEL.sendToServer(new cn.blockforge.generated.generatedmod.network.packet.HeavenlyFurnaceStartPacket(token,RECIPE,new int[]{0,-1,-1}));mc.setScreen(null);mc.options.guiScale().set(2);mc.resizeDisplay();stage=8;ticks=0;return;}
            if(stage==8){if(ticks<320)return;capture("heavenly-active-before-restart");pending=mc.getSingleplayerServer().submit(()->{var p=player(mc);var d=PortableBatch.current(p);check(d.getBoolean("InputCommitted")&&d.getString("State").equals("ACTIVE")&&V5Batch.core(d).tick()>0,"Portable batch not actually reacting");check(p.getInventory().getItem(0).getCount()==6&&p.getInventory().getItem(1).getCount()==7&&p.getInventory().getItem(2).getCount()==7,"Explicit auxiliary reservation wrong");control.addProperty("batch",d.getUUID("Id").toString());control.addProperty("coreTick",V5Batch.core(d).tick());control.addProperty("seed",V5Batch.core(d).seed());writeDoc("before-restart",d);try{Files.writeString(CONTROL,new GsonBuilder().setPrettyPrinting().create().toJson(control));}catch(Exception e){throw new RuntimeException(e);}});stage=90;return;}
            if(stage==20){if(ticks<12)return;pending=mc.getSingleplayerServer().submit(()->{var p=player(mc);var d=PortableBatch.current(p);check(d.getUUID("Id").toString().equals(control.get("batch").getAsString())&&V5Batch.core(d).seed()==control.get("seed").getAsLong()&&V5Batch.core(d).tick()>=control.get("coreTick").getAsLong(),"Restart replaced batch or rerolled core");check(p.getInventory().getItem(0).getCount()==6,"Restart refunded or reconsumed herbs");for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.DIAMOND,64));p.containerMenu.broadcastChanges();});stage=21;return;}
            if(stage==21){if(ticks<20)return;pending=mc.getSingleplayerServer().submit(()->ready=PortableBatch.current(player(mc)).getString("State").equals("READY"));stage=22;return;}
            if(stage==22){if(!ready){stage=21;return;}capture("portable-full-inventory-retained");pending=mc.getSingleplayerServer().submit(()->{var p=player(mc);var d=PortableBatch.current(p);check(d.contains("PillResult"),"Portable bypassed effects compiler");portableGrade=d.getCompound("PillResult").getInt("Grade");check(portableGrade>0,"Portable failed to produce usable compiled doses");writeDoc("portable-result",d);p.getInventory().setItem(0,ItemStack.EMPTY);p.containerMenu.broadcastChanges();});stage=23;return;}
