    private static net.minecraft.server.level.ServerPlayer player(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());}
    private static AlchemyFurnaceBlockEntity furnace(Minecraft mc){return (AlchemyFurnaceBlockEntity)mc.getSingleplayerServer().overworld().getBlockEntity(POS);}
    private static void prepare(Minecraft mc){var p=player(mc);var level=p.server.overworld();p.setNoGravity(true);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();if(RESUME)return;p.teleportTo(level,.5,201,-3,0,0);
        for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)for(int y=-1;y<6;y++)level.setBlockAndUpdate(POS.offset(x,y,z),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(POS,WuXingBlocks.ALCHEMY_FURNACE.get().defaultBlockState());CoreStructureBuilder.build(p,POS);AlchemyFurnaceStructure.refreshAround(level,POS);var f=furnace(mc);var n=f.saveWithoutMetadata();n.putInt("SpiritFuel",f.spiritCapacity());f.load(n);var r=recipe(p);
        for(int i=0;i<r.getIngredients().size();i++){var item=r.getIngredients().get(i).getItems()[0].copyWithCount(r.counts().get(i));if(HerbAge.definition(item)!=null)HerbAge.setYears(item,1500);f.setItem(i,item);}f.setItem(5,herb("xingchen"));f.setItem(8,cn.blockforge.generated.generatedmod.fire.FireBottleData.fresh(1));GeneratedMod.data(p).wuxingxiantu$learnFire(1);FormulaKnowledge.learnAll(p);net.minecraftforge.network.NetworkHooks.openScreen(p,f.menuProvider(),POS);var m=(AlchemyFurnaceMenu)p.containerMenu;int index=m.recipes().indexOf(r);check(index>=0,"Recipe absent from existing menu");m.clickMenuButton(p,2+index);
    }
    private static AlchemyRecipe recipe(net.minecraft.server.level.ServerPlayer p){return (AlchemyRecipe)p.level().getRecipeManager().byKey(RECIPE).orElseThrow();}
    private static ItemStack herb(String name){var item=new ItemStack(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse("wuxingxiantu:herb_"+name)),7);HerbAge.setYears(item,2500);return item;}
    private static void setupPortable(Minecraft mc){var p=player(mc);p.closeContainer();p.getInventory().clearContent();var d=GeneratedMod.data(p);d.wuxingxiantu$setRealm(3);d.wuxingxiantu$setAura(3200);d.wuxingxiantu$learnDivineArt(HeavenlyFurnace.ID);d.wuxingxiantu$learnFire(1);d.wuxingxiantu$setEquippedFire(1);d.wuxingxiantu$setDivineCooldown(HeavenlyFurnace.ID,0);FormulaKnowledge.learnAll(p);var r=recipe(p);for(int i=0;i<r.getIngredients().size();i++){var item=r.getIngredients().get(i).getItems()[0].copyWithCount(r.counts().get(i));if(HerbAge.definition(item)!=null)HerbAge.setYears(item,1500);p.getInventory().setItem(30+i,item);}p.getInventory().setItem(0,herb("xingchen"));p.getInventory().setItem(1,herb("hanbing"));p.getInventory().setItem(2,herb("lingdao"));p.setGameMode(GameType.SURVIVAL);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();GeneratedMod.sync(p);p.containerMenu.broadcastChanges();}
    private static void writeDoc(String name,CompoundTag d){try{Files.writeString(OUT.resolve(name+".json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("id",d.getUUID("Id").toString(),"entry",d.getString("Entry"),"state",d.getString("State"),"coreTick",V5Batch.core(d).tick(),"publicResult",d.getCompound("PillResult").toString(),"materialCount",d.getList("Materials",10).size())));}catch(Exception e){throw new RuntimeException(e);}}
    private static void check(boolean v,String message){if(!v)throw new AssertionError(message);}
    private static void capture(String name){queued.add(name);}
    static void render(Minecraft mc){if(done)return;try{while(!queued.isEmpty()){String name=queued.remove();check(org.lwjgl.opengl.GL11.glGetError()==0,"GL error");try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(OUT.resolve(name+".png"));}captures.add(name);}}catch(Throwable e){finish(mc,e.toString());}}
